def _normalize_error(error: Exception) -> CommandError:
    if isinstance(error, CommandError):
        return error
    if isinstance(error, DurabilityUnsupportedError):
        code = ErrorCode.DURABILITY_UNSUPPORTED
    elif isinstance(error, FutureSchemaError):
        code = ErrorCode.FUTURE_SCHEMA
    elif isinstance(error, StateExistsError):
        code = ErrorCode.STATE_EXISTS
    elif isinstance(error, BackupError):
        code = ErrorCode.INVALID_BACKUP
    elif isinstance(error, RevisionConflictError):
        code = ErrorCode.REVISION_CONFLICT
    elif isinstance(error, (ResourceLimitError, StateResourceLimitError)):
        code = ErrorCode.RESOURCE_LIMIT
    elif isinstance(error, StateIOError):
        code = ErrorCode.STATE_IO
    elif isinstance(error, (SchemaError, StateError)):
        code = ErrorCode.INVALID_STATE
    elif isinstance(error, OSError):
        code = ErrorCode.STATE_IO
    elif isinstance(error, ValueError):
        code = ErrorCode.USAGE
    else:
        raise error
    return CommandError(code, str(error))


def _write_json(value: object, *, stream: Any) -> None:
    stream.write(json.dumps(value, ensure_ascii=False, sort_keys=True) + "\n")


def _emit_failure(error: CommandError, *, json_output: bool) -> int:
    if json_output:
        _write_json(
            {
                "ok": False,
                "error": {
                    "code": error.code.value,
                    "message": str(error),
                    "path": error.path,
                },
            },
            stream=sys.stderr,
        )
    else:
        print(str(error), file=sys.stderr)
    return error.exit_code


def _emit_workflow(result: _WorkflowResult, *, json_output: bool) -> int:
    if json_output and result.mutation:
        payload = {
            "ok": result.exit_code == 0,
            "revision": result.revision,
            "result": result.value,
        }
        if result.status is not None:
            payload["status"] = result.status
        _write_json(payload, stream=sys.stdout)
    elif json_output:
        _write_json(result.value, stream=sys.stdout)
    else:
        if result.mutation:
            print(f"state revision {result.revision}", file=sys.stderr)
        if result.text is not None:
            print(
                result.text.rstrip("\n"),
                file=sys.stderr if result.mutation else sys.stdout,
            )
        elif not result.mutation:
            _write_json(result.value, stream=sys.stdout)
    return result.exit_code


def main(argv: Sequence[str] | None = None) -> int:
    """Run the OVCAQ command-line interface."""
    arguments = list(sys.argv[1:] if argv is None else argv)
    json_output = "--json" in arguments
    try:
        args = build_parser().parse_args(arguments)
    except CommandError as error:
        return _emit_failure(error, json_output=json_output)
    except SystemExit as error:
        return cast(int, error.code)

    try:
        root = discover_project_root(args.root)
        dispatched = _dispatch(args, root)
    except (
        CommandError,
        StateError,
        SchemaError,
        OSError,
        ValueError,
    ) as error:
        return _emit_failure(_normalize_error(error), json_output=args.json)

    if isinstance(dispatched, _WorkflowResult):
        return _emit_workflow(dispatched, json_output=args.json)

    result, revision, mutation = dispatched
    if args.json and mutation:
        _write_json(
            {"ok": True, "revision": revision, "result": result},
            stream=sys.stdout,
        )
    elif mutation:
        print(f"state revision {revision}", file=sys.stderr)
    else:
        _write_json(result, stream=sys.stdout)
    return 0

from __future__ import annotations

import os
import stat
import tomllib
from collections.abc import Collection, Mapping
from dataclasses import dataclass
from pathlib import Path

from ovcaq.paths import CONFIG_NAME, runtime_directory


class ConfigurationError(ValueError):
    """Raised when a workflow configuration input has an invalid shape."""


def ensure_project_config(root: Path) -> Path:
    path = root / CONFIG_NAME
    try:
        path.touch(exist_ok=False)
    except FileExistsError:
        if not path.is_file():
            raise
    return path


@dataclass(frozen=True)
class WorkflowSettings:
    prd_root: Path
    runtime_root: Path
    state_file: Path
    available_tiers: frozenset[str]


def _read_config(path: Path) -> dict[str, object]:
    try:
        descriptor = os.open(
            path,
            os.O_RDONLY
            | os.O_NONBLOCK
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0),
        )
        with os.fdopen(descriptor, "rb") as stream:
            if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                raise ConfigurationError(f"configuration is not a regular file: {path}")
            return tomllib.load(stream)
    except FileNotFoundError:
        return {}
    except RecursionError as error:
        raise ConfigurationError(
            f"configuration nesting exceeds safe decode limit: {path}"
        ) from error
    except OSError as error:
        raise ConfigurationError(
            f"cannot read configuration {path}: {error}"
        ) from error


def _table(config: Mapping[str, object], key: str) -> Mapping[str, object]:
    value = config.get(key, {})
    if not isinstance(value, dict):
        raise ConfigurationError(f"configuration {key} must be a table")
    return value


def _configured_path(root: Path, value: object, label: str) -> Path:
    if not isinstance(value, (str, Path)) or not str(value):
        raise ConfigurationError(f"configuration {label} must be a nonempty path")
    path = Path(value).expanduser()
    return path if path.is_absolute() else root / path


def workflow_settings(
    root: Path,
    *,
    prd_root: Path | None = None,
    runtime_root: Path | None = None,
    state_file: Path | None = None,
    available_tiers: Collection[str] | None = None,
) -> WorkflowSettings:
    """Resolve only workflow inputs; model values and runtime policy stay opaque."""
    config_home = Path(os.environ.get("XDG_CONFIG_HOME", Path.home() / ".config"))
    user = _read_config(config_home / "ovcaq/config.toml")
    project = _read_config(root / CONFIG_NAME)
    workflow = {**_table(user, "workflow"), **_table(project, "workflow")}
    prds = _configured_path(
        root, prd_root or workflow.get("prd_root", "dev/local/prds"), "prd_root"
    )
    runtime = _configured_path(
        root,
        runtime_root or workflow.get("runtime_root", "dev/local/ovcaq"),
        "runtime_root",
    )
    runtime = runtime_directory(root, runtime)
    state = _configured_path(root, state_file or runtime / "state.json", "state_file")
    tiers: dict[str, object] = {}
    active = project.get("agent", user.get("agent"))
    if active is not None:
        if not isinstance(active, str) or not active:
            raise ConfigurationError("configuration agent must be a nonempty name")
        for config in (user, project):
            agent = _table(_table(config, "agents"), active)
            tiers.update(_table(agent, "tiers"))
    return WorkflowSettings(
        prds,
        runtime,
        state,
        frozenset(tiers if available_tiers is None else available_tiers),
    )

from __future__ import annotations

import os
import stat
from pathlib import Path

CONFIG_NAME = "ovcaq.toml"
RUNTIME_PARTS = ("dev", "local", "ovcaq")


class ProjectPathError(OSError):
    """Raised when a derived project path can escape its resolved root."""


def _derived_runtime_path(root: Path) -> Path:
    return root.joinpath(*RUNTIME_PARTS)


def _reject_symlink_components(root: Path, derived: Path) -> None:
    current = root
    for component in derived.relative_to(root).parts:
        current /= component
        try:
            mode = current.lstat().st_mode
        except FileNotFoundError:
            continue
        except OSError as error:
            raise ProjectPathError(
                f"cannot inspect derived runtime path {current}: {error}"
            ) from error
        if stat.S_ISLNK(mode):
            raise ProjectPathError(
                f"derived runtime path contains a symlink: {current}"
            )


def _validated_runtime_path(root: Path, configured_root: Path | None = None) -> Path:
    resolved_root = root.expanduser().resolve()
    derived = (
        _derived_runtime_path(resolved_root)
        if configured_root is None
        else configured_root
    )
    if not derived.is_absolute():
        derived = resolved_root / derived
    try:
        derived.relative_to(resolved_root)
    except ValueError as error:
        raise ProjectPathError(
            f"derived runtime path escapes project root: {derived}"
        ) from error
    _reject_symlink_components(resolved_root, derived)
    try:
        derived.resolve().relative_to(resolved_root)
    except ValueError as error:
        raise ProjectPathError(
            f"derived runtime path escapes project root {resolved_root}: {derived}"
        ) from error
    return derived


def _is_runtime_marker(root: Path) -> bool:
    try:
        return runtime_directory(root).is_dir()
    except ProjectPathError:
        return False


def discover_project_root(
    explicit_root: Path | None = None,
    *,
    start: Path | None = None,
) -> Path:
    if explicit_root is not None:
        return explicit_root.expanduser().resolve()

    current = (Path.cwd() if start is None else start).resolve()
    candidates = (current, *current.parents)
    for candidate in candidates:
        if (candidate / CONFIG_NAME).is_file() or _is_runtime_marker(candidate):
            return candidate
    for candidate in candidates:
        if (candidate / ".git").exists():
            return candidate
    return current


def runtime_directory(root: Path, configured_root: Path | None = None) -> Path:
    return _validated_runtime_path(root, configured_root)


def ensure_runtime_directory(root: Path) -> Path:
    resolved_root = root.expanduser().resolve()
    resolved_root.mkdir(parents=True, exist_ok=True)
    current = resolved_root
    for index, component in enumerate(RUNTIME_PARTS):
        candidate = current / component
        _reject_symlink_components(resolved_root, candidate)
        try:
            mode = 0o700 if index == len(RUNTIME_PARTS) - 1 else 0o777
            candidate.mkdir(mode=mode)
        except FileExistsError:
            if not candidate.is_dir():
                raise ProjectPathError(
                    f"derived runtime path is not a directory: {candidate}"
                ) from None
        _reject_symlink_components(resolved_root, candidate)
        current = candidate

    runtime = _validated_runtime_path(resolved_root)
    descriptor = -1
    try:
        flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(runtime, flags)
        if not stat.S_ISDIR(os.fstat(descriptor).st_mode):
            raise ProjectPathError(f"runtime path is not a directory: {runtime}")
        if runtime.is_symlink():
            raise ProjectPathError(f"runtime path is a symlink: {runtime}")
        os.fchmod(descriptor, 0o700)
    except OSError as error:
        if isinstance(error, ProjectPathError):
            raise
        raise ProjectPathError(
            f"cannot secure runtime directory {runtime}: {error}"
        ) from error
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    return runtime


def state_path(root: Path) -> Path:
    return runtime_directory(root) / "state.json"

from __future__ import annotations

import ast
from pathlib import Path

WORKFLOW_ROOT = Path("src/ovcaq/workflow")
FORBIDDEN_IMPORT_PREFIXES = (
    "ovcaq.drivers",
    "ovcaq.events",
    "ovcaq.provision",
    "ovcaq.runtime",
    "ovcaq.tui",
)
FORBIDDEN_STRINGS = (
    "anthropic",
    "claude",
    "codex",
    "qwen",
    "dev/local/autopilot",
    ".claude",
    ".codex",
)
FORBIDDEN_SKILL_COMMANDS = (
    "/run-autopilot",
    "/review-work-completion",
    "/work",
)


def test_workflow_imports_only_state_workflow_and_standard_library() -> None:
    violations: list[str] = []
    for path in sorted(WORKFLOW_ROOT.glob("*.py")):
        tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
        for node in ast.walk(tree):
            names: tuple[str, ...] = ()
            if isinstance(node, ast.Import):
                names = tuple(alias.name for alias in node.names)
            elif isinstance(node, ast.ImportFrom) and node.module is not None:
                names = (node.module,)
            for name in names:
                if name.startswith(FORBIDDEN_IMPORT_PREFIXES):
                    violations.append(f"{path}:{node.lineno}: {name}")
    assert violations == []


def test_workflow_contains_no_provider_or_legacy_runtime_strings() -> None:
    violations: list[str] = []
    for path in sorted(WORKFLOW_ROOT.glob("*.py")):
        text = path.read_text(encoding="utf-8").lower()
        for forbidden in FORBIDDEN_STRINGS:
            if forbidden in text:
                violations.append(f"{path}: {forbidden}")
    assert violations == []


def test_workflow_contains_no_external_skill_commands() -> None:
    violations: list[str] = []
    for path in sorted(WORKFLOW_ROOT.glob("*.py")):
        text = path.read_text(encoding="utf-8").lower()
        for command in FORBIDDEN_SKILL_COMMANDS:
            if command in text:
                violations.append(f"{path}: {command}")
    assert violations == []

